Module PNADB6N.
Import PMS.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation AQ := PnLayoutQS.QADDR_S.
Abbreviation kstr_at := (PQM.kstr_at RSEGS PMSP.T3).
Abbreviation adaptor_at := (PQM.adaptor_at RSEGS AD PMSP.T3 PMSP.T4 (qa_vp_adaptor AQ)).
