Definition ALPH : Z := 89127.

(* [comment removed for export] *)
Lemma b64len_eq n k r : n = 3 * k + r -> 0 <= r <= 2 -> 0 <= k -> PQV.b64len n = 4 * k + (if Z.eqb r 0 then 0 else r + 1).
Proof.
ltac2:(KReplay.run1 (kr_t_PnAdB64N ()) [] (Mh_0190_blobs1.kr_b_064 ())). Qed.
Lemma b64len_range n : 0 <= n -> 0 <= PQV.b64len n <= 2 * n + 1.
Proof.
ltac2:(KReplay.run1 (kr_t_PnAdB64N ()) [] (Mh_0190_blobs1.kr_b_065 ())). Qed.
Lemma writable0 M a : L5.writable RSEGS M a 0.
Proof.
ltac2:(KReplay.run1 (kr_t_PnAdB64N ()) [] (Mh_0190_blobs1.kr_b_066 ())). Qed.

(* [comment removed for export] *)
Definition alph_chk : bool := forallb (fun i => match AX2.img_bytes RSEGS (ALPH + Z.of_nat i) 1 with Some [z] => (0 <=? z) && (z <? 128) | _ => false end) (seq 0 256).
Lemma alph_chk_ok : alph_chk = true.
Proof.
ltac2:(KReplay.run1 (kr_t_PnAdB64N ()) [] (Mh_0190_blobs1.kr_b_067 ())). Qed.
Lemma alph_ok i : 0 <= i < 256 -> exists z, AX2.img_bytes RSEGS (ALPH + i) 1%nat = Some [z] /\ 0 <= z < 128.
Proof.
ltac2:(KReplay.run1 (kr_t_PnAdB64N ()) [] (Mh_0190_blobs1.kr_b_068 ())). Qed.
(* [comment removed for export] *)
Lemma alph_step (fx : FPState) R M (pc : Z) (W : bv 32) (i : Z) :
  fetch_word RSEGS (Z_to_bv 64 pc) = Some W -> is_ecall W = false -> decode_any W = Some (Load SZ1 false 11 10 0, 4%Z) ->
  L5.img_clear M 65536 814272 -> getr R (reg 10) = Z_to_bv 64 (i + ALPH) -> 0 <= i < 256 -> 0 <= pc -> pc + 4 < 2 ^ 64 ->
  exists ch, 0 <= ch < 128 /\ msteps RSEGS (mst fx R pc M) (mst fx (regupd R 11%bv (Z_to_bv 64 ch)) (pc + 4) M).
Proof.
ltac2:(KReplay.run1 (kr_t_PnAdB64N ()) [] (Mh_0190_blobs1.kr_b_069 ())). Qed.
Lemma upd11_same R ch : 0 <= ch < 2 ^ 64 -> getr (regupd R 11%bv (Z_to_bv 64 ch)) (reg 11) = Z_to_bv 64 ch.
Proof.
ltac2:(KReplay.run1 (kr_t_PnAdB64N ()) [] (Mh_0190_blobs1.kr_b_070 ())). Qed.
Lemma upd11_other R ch k : k <> 11%nat -> (k < 32)%nat -> getr (regupd R 11%bv (Z_to_bv 64 ch)) (reg k) = getr R (reg k).
Proof.
ltac2:(KReplay.run1 (kr_t_PnAdB64N ()) [] (Mh_0190_blobs1.kr_b_071 ())). Qed.

Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
