Definition ENVX (cnt : Z) : nat -> Z := fun z => match z with 2%nat => sp1 | 36%nat => oa + 24 | 35%nat => cnt
  | 40%nat => bv_unsigned (getr R0 (reg 1)) | 41%nat => bv_unsigned (getr R0 (reg 8)) | 42%nat => bv_unsigned (getr R0 (reg 9))
  | 43%nat => bv_unsigned (getr R0 (reg 18)) | 44%nat => bv_unsigned (getr R0 (reg 19)) | 45%nat => bv_unsigned (getr R0 (reg 20)) | 46%nat => bv_unsigned (getr R0 (reg 21))
  | 47%nat => bv_unsigned (getr R0 (reg 22)) | 48%nat => bv_unsigned (getr R0 (reg 23)) | 49%nat => bv_unsigned (getr R0 (reg 24)) | 50%nat => bv_unsigned (getr R0 (reg 25)) | _ => 0 end.

