Lemma GL3 (i cur : Z) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (ky : PM.vstr) (kgy : Z) (cr : credit) (ds : list Z) (idx cnt : Z) :
  0 <= i < n -> cur = d + i -> i mod 3 = 2 ->
  (forall (fxc : FPState) (Rc : bvmap 5 word) (Mc : word -> option byte) (modelc : Model) (kyc : PM.vstr) (kgyc : Z) (crc : credit) (dsc : list Z) (cntc : Z),
      i + 1 < n -> LREG Rc -> getr Rc (reg 21) = Z_to_bv 64 (cur + 1) -> getr Rc (reg 22) = Z_to_bv 64 0 -> getr Rc (reg 20) = Z_to_bv 64 (d + n) -> getr Rc (reg 8) = Z_to_bv 64 cntc -> 3 * cntc = 4 * (i + 1) ->
      saves Mc -> cm Mc -> world Mc -> AG Mc -> ABK Mc -> ERK Mc -> adaptor_at Mc oa ov (stK kyc kgyc) -> kcontent Mc (oa + 24) kyc (bs0 ++ dsc) -> NEM.ascii dsc -> PQM.ks_ok PQM.SMK kyc kgyc -> 3 * (PM.vs_size kyc - PM.vs_size kx) = 4 * (i + 1) ->
