      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fxc Rc 0x3ed08 Mc modelc) K) ->
  LREG R -> getr R (reg 10) = Z_to_bv 64 (idx + ALPH) -> 0 <= idx < 256 -> getr R (reg 8) = Z_to_bv 64 cnt -> 3 * cnt = 4 * (i - 2) ->
  getr R (reg 20) = Z_to_bv 64 (d + n) -> getr R (reg 21) = Z_to_bv 64 cur -> getr R (reg 22) = Z_to_bv 64 (sp1 - 95 + 3) ->
  saves M -> cm M -> world M -> AG M -> ABK M -> ERK M -> adaptor_at M oa ov (stK ky kgy) -> kcontent M (oa + 24) ky (bs0 ++ ds) -> NEM.ascii ds -> PQM.ks_ok PQM.SMK ky kgy -> 3 * (PM.vs_size ky - 3 - PM.vs_size kx) = 4 * (i - 2) ->
  PMSP.credit_keep cr1 cr (PQM.pot_adaptor L (stK kx kgx)) (PQM.pot_adaptor L (stK ky kgy)) -> model_but_vm model1 model ->
  hi_heap HI (PQM.aown (stK ky kgy) ++ LBX) cr M (m_vmmaps model) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x3ed6c M model) K.
